def find_Min(arr, low, high):
    # Base case: if the array is empty or has only one element, return the element itself
    if low == high:
        return arr[low]
    # Find the middle index
    mid = (low + high) // 2
    # Check if the middle element is the minimum
    if arr[mid] < arr[mid + 1]:
        return arr[mid]
    # If the middle element is greater than the element at the next index, the minimum is in the left half
    elif arr[mid] > arr[mid + 1]:
        return find_Min(arr, low, mid - 1)
    # If the middle element is less than the element at the next index, the minimum is in the right half
    else:
        return find_Min(arr, mid + 1, high)

