def lps(s):
    # Initialize a 2D array to store the lengths of longest palindromic subsequences
    dp = [[0] * len(s) for _ in range(len(s))]

    # Fill the dp array
    for i in range(len(s)):
        for j in range(len(s)):
            if i == j:
                dp[i][j] = 1
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # The length of the longest palindromic subsequence is the value in the bottom-right corner of the dp array
    return dp[0][len(s) - 1]

